def is_valid(meter):
    """Return True if meter is a valid tuple representation of a meter.

    Examples for meters are (3,4) for 3/4, (4,4) for 4/4, etc.
    """
    return meter[0] > 0 and valid_beat_duration(meter[1])

def is_valid_key(key):
    """Return True if key is in a recognized format. False if not."""
    for couple in keys:
        if key in couple:
            return True
    return False

def change_note_duration(self, at, to):
    """Change the note duration at the given index to the given
    duration."""
    if _meter.valid_beat_duration(to):
        diff = 0
        for x in self.bar:
            if diff != 0:
                x[0][0] -= diff
            if x[0] == at:
                cur = x[0][1]
                x[0][1] = to
                diff = 1 / cur - 1 / to
